use std::fs

struct Tree {
    keys: Vec<int>,
    l: Vec<int>,
    r: Vec<int>,
    found: bool,
}

fn insert(t: Tree, node: int, x: int) -> int {
    if node < 0 {
        t.keys.push(x)
        t.l.push(-1)
        t.r.push(-1)
        return (t.keys.len() as int) - 1
    }
    let k = t.keys[node as usize]
    if x < k {
        let c = t.l[node as usize]
        let n = insert(t, c, x)
        t.l[node as usize] = n
    } else if x > k {
        let c = t.r[node as usize]
        let n = insert(t, c, x)
        t.r[node as usize] = n
    } else {
        t.found = true
    }
    node
}

fn min_node(t: Tree, node: int) -> int {
    let mut n = node
    while t.l[n as usize] >= 0 {
        n = t.l[n as usize]
    }
    n
}

fn delete(t: Tree, node: int, x: int) -> int {
    if node < 0 {
        return -1
    }
    let k = t.keys[node as usize]
    if x < k {
        let c = t.l[node as usize]
        let n = delete(t, c, x)
        t.l[node as usize] = n
    } else if x > k {
        let c = t.r[node as usize]
        let n = delete(t, c, x)
        t.r[node as usize] = n
    } else {
        t.found = true
        let a = t.l[node as usize]
        let b = t.r[node as usize]
        if a < 0 {
            return b
        }
        if b < 0 {
            return a
        }
        let s = min_node(t, b)
        let sk = t.keys[s as usize]
        t.keys[node as usize] = sk
        let n = delete(t, b, sk)
        t.r[node as usize] = n
    }
    node
}

fn inorder(t: Tree, node: int, out: Vec<string>) {
    if node < 0 {
        return
    }
    inorder(t, t.l[node as usize], out)
    out.push("${t.keys[node as usize]}")
    inorder(t, t.r[node as usize], out)
}

fn height(t: Tree, node: int) -> int {
    if node < 0 {
        return 0
    }
    let a = height(t, t.l[node as usize])
    let b = height(t, t.r[node as usize])
    if a > b { a + 1 } else { b + 1 }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], l: [], r: [], found: false }
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            t.found = false
            root = insert(t, root, x)
            if t.found { println("dup") } else { println("ok") }
        } else if cmd == "contains" {
            let mut n = root
            let mut f = false
            while n >= 0 {
                let k = t.keys[n as usize]
                if x == k {
                    f = true
                    break
                }
                n = if x < k { t.l[n as usize] } else { t.r[n as usize] }
            }
            if f { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            t.found = false
            root = delete(t, root, x)
            if t.found { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            inorder(t, root, out)
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            println("${height(t, root)}")
        } else if cmd == "min" {
            if root < 0 { println("empty") } else { println("${t.keys[min_node(t, root) as usize]}") }
        } else if cmd == "max" {
            if root < 0 {
                println("empty")
